                      (word.obj.yDesc.length > previewCharLimit && dopreview ?
                        <span>{word.obj.yDesc.substring(0,previewCharLimit)}<span style={{color:'grey'}}>{'...'}</span></span>
                        :
                        <span>{word.obj.yDesc}</span>
                      )       
                    }
                    </div>                    
                    </Grid.Column>
                  </Grid.Row>

                  {index in this.state.activeAudioIndex ?
                    <Grid.Row columns={2}>
                      <Grid.Column>
                        {'m'+word.obj.id+'_e2' in this.props.audioFiles ?
                          <div>
                            <audio controls style={{width:'-webkit-fill-available',height:40}} src={API_URL + "/aijaudiolibrary/"+'m'+word.obj.id+'_e2'} />
                          </div>
                          :
                          null
                        }   
                      </Grid.Column>
                      <Grid.Column>
                        {'m'+word.obj.id+'_y2' in this.props.audioFiles ?
                          <div>
                            <audio controls style={{width:'-webkit-fill-available',height:40}} src={API_URL + "/aijaudiolibrary/"+'m'+word.obj.id+'_y2'} />
                          </div>
                          :
                          null
                        }  
                      </Grid.Column>
                    </Grid.Row>
                    :
                    null
                  }

                  {index in this.state.activeAudioIndex ?
                    <Grid.Row>
                    <Grid.Column>
                    <div style={{display:'flex',lineHeight:'21px',fontSize:'15px'}}>
                      <div style={{flex:1}} />
                      <div style={{flex:3,paddingRight:'6px'}}>
{/*                        <div>
                        <span style={{fontWeight:'500'}}>{'Translator: '}</span>
                        </div>
                        <div>
                        <span style={{fontWeight:'500'}}>{'Speaker: '}</span>
                        </div>*/}
                        <div>
                        <span style={{fontWeight:'500'}}>{'Resource: '}</span>
                        </div>                    
                      </div>
                      <div style={{flex:13}}>
{/*                        <div>
                        <span>{'Veronica Kaganak'}</span>
                        </div>
                        <div>
                        <span>{'Veronica Kaganak'}</span>
                        </div>*/}
                        <div>
                        <a target="_blank" href={'https://www.akijp.org/yugtun-medical-resources/?a=' + word.obj.resourceID}>
                          <span style={{cursor:'pointer',color:'#4a80b5'}}>{this.props.resourceIDs[word.obj.resourceID][0][0]+' - '+this.props.resourceIDs[word.obj.resourceID][1][0]}</span>
                        </a>
                        </div>
                      </div>
                      <div style={{flex:1}} />
                    </div>
                    </Grid.Column>
                    </Grid.Row>
                    :
                    null
                  }


                  {'m'+word.obj.id+'_e2' in this.props.audioFiles  || 'm'+word.obj.id+'_y2' in this.props.audioFiles ?
                    <Grid.Row style={{paddingTop:0,fontSize:'14px',justifyContent:'flex-end'}}>
                    <Button style={{marginRight:'14px'}} onClick={()=>this.setActiveAudioIndex(word,index)} basic>
                    <div style={{color:'#A2A2A2'}}>
                    {'More Audio'}
                    {index in this.state.activeAudioIndex ?
                      <Icon style={{paddingLeft:'5px'}} name='chevron up' />
                      :
                      <Icon style={{paddingLeft:'5px'}} name='chevron down' />
                    }                    
                    </div>
                    </Button>
                    </Grid.Row>
                    :
                    <Grid.Row style={{padding:9}} />
                  }

                </Grid>
						    })
						    :
						    null
              	}
          </div>
          :
          null
        }

        <List>
      	<div>

          {emptyList ? <div style={{padding:20,textAlign:'center',fontSize:'16px',fontStyle:'italic'}}>No matches...</div>: ''}


          {!displayList && this.state.homeMode === 0 && !emptyList ? 
            <div style={{display:'flex',justifyContent:'center',padding:'30px 0px',marginBottom:'20px'}}>
              <div style={{fontSize:'1.2rem',color:'#555555',lineHeight:1.6,maxWidth:550}}>
                <div>
                <div style={{marginBottom:10}}> Type any English or Yugtun word and matching behavioral health terms will show automatically.</div>
                <div> Examples: </div>
                <div>
                <span onClick={()=>{this.setState({search:"Stigma",wordsList: fuzzysort.go("Stigma", this.props.masterMedicalList, options1)})}} style={{color:'#4A80B5',cursor:'pointer'}}>Stigma</span>
                <span>{', '}</span>
                <span onClick={()=>{this.setState({search:"Umyuarniurun",wordsList: fuzzysort.go('Umyuarniurun', this.props.masterMedicalList, options1)})}} style={{color:'#4A80B5',cursor:'pointer'}}>Umyuarniurun</span>
