                <span>{', '}</span>
                <span onClick={()=>{this.setState({search:"Piciunritniyaraq",wordsList: fuzzysort.go('Piciunritniyaraq', this.props.masterMedicalList, options1)})}} style={{color:'#4A80B5',cursor:'pointer'}}>Piciunritniyaraq</span>
                </div>
                </div>


